#pragma once
#include "ksStatePlaybackModeCoordinator.h"
#include "ksStatePlaybackResetService.h"
#include "ksStateProgramLoadService.h"
#include "ksStateFieldService.h"
namespace ks {
// Complete mode/playback transaction, including real program reload, recursive
// UI editing, per-part voice release and interruptible MIDI transmission.
class StatePlaybackModeService final {
public:
 using Kind=StatePlaybackModeCoordinator::Kind;using Input=StatePlaybackModeCoordinator::Input;using Effect=StatePlaybackModeCoordinator::Effect;
 enum class Component{Action,Reset,Routing,Storage,Resolve,EditPart,Digits,Ui,Program,HeldKeys,Voices,Midi,Lookup,Serial};
 explicit StatePlaybackModeService(Kind k):StatePlaybackModeService(k,Input{}){}
 StatePlaybackModeService(Kind k,Input i):coordinator_(k,i){components_=1u<<unsigned(component());}
 Kind kind()const{return coordinator_.kind();}const Input&input()const{return coordinator_.input();}const StatePlaybackModeCoordinator&coordinator()const{return coordinator_;}const auto&summary()const{return coordinator_.summary();}
 bool complete()const{return coordinator_.complete();}bool critical()const{return active_==Active::Ui?ui_->critical():active_==Active::Program?program_->critical():active_==Active::Reset?reset()->critical():false;}const Effect&effect()const{return effect_;}uint32_t components()const{return components_;}
 const StateFieldService*ui()const{return ui_?&*ui_:nullptr;}const StateProgramLoadService*program()const{return program_?&*program_:nullptr;}const StatePlaybackResetService*reset()const{return resetIndex_<resets_.size()&&resets_[resetIndex_]?&*resets_[resetIndex_]:nullptr;}const StatePlaybackResetService*resetOutcome(unsigned n)const{return n<resets_.size()&&resets_[n]?&*resets_[n]:nullptr;}
 Component component()const{if(active_==Active::Ui)return Component::Ui;if(active_==Active::Program)return Component::Program;if(active_==Active::Reset){switch(reset()->component()){case StatePlaybackResetService::Component::Keys:return Component::HeldKeys;case StatePlaybackResetService::Component::Voices:return Component::Voices;case StatePlaybackResetService::Component::Midi:return Component::Midi;case StatePlaybackResetService::Component::Lookup:return Component::Lookup;case StatePlaybackResetService::Component::Serial:return Component::Serial;}}return Component(unsigned(coordinator_.component()));}
 template<class T>const T*task()const{if(active_==Active::Ui){if constexpr(std::is_same_v<T,StateFieldCoordinator>||std::is_same_v<T,StateApplyService>||std::is_same_v<T,StateDisplayService>||std::is_same_v<T,StateScreenService>||std::is_same_v<T,StateUiRefreshService>||std::is_same_v<T,StateStoreService>||std::is_same_v<T,StateFieldPacketService>||std::is_same_v<T,PanelSettingsLcdService>||std::is_same_v<T,StateSceneCoordinator>||std::is_same_v<T,StateSceneEditCoordinator>||std::is_same_v<T,StateVoiceRefreshService>)return ui_->template task<T>();else return nullptr;}if(active_==Active::Program)return program_->template task<T>();if(active_==Active::Reset)return reset()->template task<T>();return coordinator_.template task<T>();}
 template<class Peek,class Resolver>static bool admitted(Kind k,const Input&i,Peek&&peek,Resolver&&resolver){if((k==Kind::Single||k==Kind::Multi)&&i.pressed){if(!StateProgramLoadService::admitted(k==Kind::Single?StateProgramLoadService::Kind::CommitSingle:StateProgramLoadService::Kind::CommitMulti,peek,[&](uint8_t category,uint32_t raw){return resolver.schema(category,raw);}))return false;}if(((k==Kind::Single||k==Kind::Multi)&&i.pressed)||k==Kind::Playback||k==Kind::ResetPlayback||k==Kind::ResetVoices){if(peek(0xffed6c)||peek(0xffed6e))return false;}return true;}
 unsigned nextClocks(int previous=-1)const{if(active_==Active::Ui)return ui_->nextClocks(previous);if(active_==Active::Program)return program_->nextClocks(previous);if(active_==Active::Reset)return reset()->nextClocks(previous);return coordinator_.nextClocks(previous);}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned available,R&&read,W&&write,Resolver&&resolver,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>available)return 0;effect_={};components_|=1u<<unsigned(component());if(active_==Active::Ui){ui_->advanceBefore(cost,read,write,resolver,previous);effect_={ui_->effect().read,ui_->effect().write};if(ui_->complete()){const auto*u=ui_->refresh();coordinator_.resume(u?u->summary().character:coordinator_.presentation());active_=Active::Coordinator;}}
 else if(active_==Active::Program){program_->advanceBefore(cost,read,write,[&](uint8_t category,uint32_t raw){return resolver.schema(category,raw);},previous);effect_={program_->effect().read,program_->effect().write};if(program_->complete()){coordinator_.resume(program_->presentation());active_=Active::Coordinator;}}
 else if(active_==Active::Reset){auto&s=*resets_[resetIndex_];s.advanceBefore(cost,read,write,previous);effect_={s.effect().read,s.effect().write};if(s.complete()){coordinator_.resume(coordinator_.presentation());active_=Active::Coordinator;}}
 else{coordinator_.advanceBefore(cost,read,write,resolver,previous);effect_=coordinator_.effect();using Q=StatePlaybackModeCoordinator::Request;switch(coordinator_.request()){case Q::None:break;case Q::Ui:if(ui_)throw std::logic_error("Repeated mode UI ownership");ui_.emplace(StateUiRefreshService::Kind::Refresh,StateUiRefreshService::Input{0,coordinator_.presentation(),coordinator_.presentation()});active_=Active::Ui;break;case Q::SingleProgram:case Q::MultiProgram:if(program_)throw std::logic_error("Repeated mode program ownership");program_.emplace(coordinator_.request()==Q::SingleProgram?StateProgramLoadService::Kind::CommitSingle:StateProgramLoadService::Kind::CommitMulti,StateProgramLoadService::Input{coordinator_.presentation()});active_=Active::Program;break;case Q::HeldKeys:case Q::ReleaseVoices:case Q::Panic:resetIndex_=coordinator_.requestIndex();if(resetIndex_>=resets_.size()||resets_[resetIndex_])throw std::logic_error("Mode reset outcome capacity");resets_[resetIndex_].emplace(coordinator_.request()==Q::HeldKeys?StatePlaybackResetService::Kind::HeldKeys:coordinator_.request()==Q::ReleaseVoices?StatePlaybackResetService::Kind::ReleaseVoices:StatePlaybackResetService::Kind::Panic);active_=Active::Reset;break;}}
 components_|=1u<<unsigned(component());return cost;}
private:
 enum class Active{Coordinator,Ui,Program,Reset};StatePlaybackModeCoordinator coordinator_;Active active_=Active::Coordinator;Effect effect_{};uint32_t components_=0;unsigned resetIndex_=~0u;std::optional<StateFieldService>ui_;std::optional<StateProgramLoadService>program_;std::array<std::optional<StatePlaybackResetService>,24>resets_{};
};
}
